<template><div class="page-container"><PageHeader>数据字典</PageHeader>
<el-alert title="字典项停用后不再出现在业务下拉框中，历史业务数据保持不变。" type="info" :closable="false" show-icon style="margin-bottom:16px"/>
<div class="filter-bar"><el-select v-model="type" clearable placeholder="字典类型" style="width:220px" @change="search"><el-option v-for="x in types" :key="x.value" :label="x.label" :value="x.value"/></el-select><el-button type="primary" @click="search">查询</el-button><el-button type="success" @click="open()">新增字典项</el-button></div>
<el-table :data="rows" v-loading="loading" border stripe><el-table-column label="字典类型" min-width="160"><template #default="{row}">{{ typeText(row.dictType) }}</template></el-table-column><el-table-column prop="itemCode" label="编码" min-width="130"/><el-table-column prop="itemLabel" label="显示名称" min-width="150"/><el-table-column prop="sortOrder" label="排序" width="80"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column prop="remark" label="备注" min-width="180"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button></template></el-table-column></el-table>
<div style="margin-top:16px;display:flex;justify-content:flex-end"><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" :page-sizes="[20,50,100]" layout="total,sizes,prev,pager,next" @change="load"/></div>
<el-dialog v-model="visible" :title="form.id?'编辑字典项':'新增字典项'" width="520px"><el-form label-width="90px"><el-form-item label="字典类型" required><el-select v-model="form.dictType" :disabled="!!form.id" filterable style="width:100%"><el-option v-for="x in types" :key="x.value" :label="x.label" :value="x.value"/></el-select></el-form-item><el-form-item label="编码" required><el-input v-model="form.itemCode" :disabled="!!form.id" placeholder="英文编码"/></el-form-item><el-form-item label="显示名称" required><el-input v-model="form.itemLabel"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder" :min="0"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import PageHeader from '@/components/PageHeader.vue';import*as api from '@/api/dictionaries';
const types=[{value:'PRODUCT_CATEGORY',label:'备件分类'},{value:'UNIT',label:'计量单位'},{value:'DEPARTMENT',label:'领用部门'},{value:'DELIVERY_LOCATION',label:'交付地点'},{value:'WAREHOUSE',label:'仓库名称'},{value:'LOCATION_AREA',label:'库位区域'},{value:'LOCATION_TYPE',label:'库位类型'},{value:'EQUIPMENT_STATUS',label:'设备状态'},{value:'EQUIPMENT_ZONE',label:'设备区域'}];const type=ref(''),rows=ref([]),loading=ref(false),page=ref(1),size=ref(20),total=ref(0),visible=ref(false),form=ref({});const typeText=v=>types.find(x=>x.value===v)?.label||v;async function load(){loading.value=true;try{const r=await api.list({type:type.value||undefined,page:page.value-1,size:size.value});rows.value=r.content||[];total.value=r.totalElements||0}finally{loading.value=false}}function search(){page.value=1;load()}function open(row){form.value=row?{...row}:{dictType:type.value||'',itemCode:'',itemLabel:'',sortOrder:0,enabled:true,remark:''};visible.value=true}async function save(){if(!form.value.dictType||!form.value.itemCode.trim()||!form.value.itemLabel.trim()){ElMessage.warning('请完整填写字典类型、编码和显示名称');return}const data={...form.value,itemCode:form.value.itemCode.trim(),itemLabel:form.value.itemLabel.trim()};form.value.id?await api.update(form.value.id,data):await api.create(data);ElMessage.success('保存成功');visible.value=false;load()}onMounted(load)</script>
